tatic/images/DBMS.svg" width="16"/> DBMS</a></li><li class="nav-item"><a class="nav-link" href="/operating-system"><img alt="Operating System" height="16" src="https://tpointtech-images.s3.eu-north-1.amazonaws.com/static/images/OS.svg" width="16"/> OS</a></li><li class="nav-item"><a class="nav-link" href="/aptitude/quantitative"><img alt="aptitude" height="16" src="https://tpointtech-images.s3.eu-north-1.amazonaws.com/static/images/Aptitude.svg" width="16"/> Aptitude</a></li><li class="nav-item"><a class="nav-link" href="/reasoning"><img alt="reasoning" height="16" src="https://tpointtech-images.s3.eu-north-1.amazonaws.com/static/images/Reasoning.svg" width="16"/> Reasoning</a></li></ul></div></div></div><section class="course-details"><div class="container-fluid"><div class="row"><div class="col-md-2 sidebar" id="sidebar"><div id="menu-sidebar"><div class="accordion accordion-flush" id="accordionFlushExample"><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading0"><button aria-controls="flush-collapse0" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse0" data-bs-toggle="collapse" type="button">Java 8 Date Time</button></h2><div aria-labelledby="flush-heading0" class="accordion-collapse collapse show" id="flush-collapse0"><div class="accordion-body"><ul><li class="leftmenu"><a href="/java-date">Java Date Time API</a></li><li class="leftmenu"><a href="/java-localdate">Java LocalDate</a></li><li class="leftmenu"><a href="/java-localtime">Java LocalTime</a></li><li class="leftmenu"><a href="/java-localdatetime">Java LocalDateTime</a></li><li class="leftmenu"><a href="/java-monthday">Java MonthDay</a></li><li class="leftmenu"><a href="/java-offsettime">Java OffsetTime</a></li><li class="leftmenu"><a href="/java-offsetdatetime">Java OffsetDateTime</a></li><li class="leftmenu"><a href="/java-clock">Java Clock</a></li><li class="leftmenu"><a href="/java-zoneddatetime">Java ZonedDateTime</a></li><li class="leftmenu"><a href="/java-zoneid">Java ZoneId</a></li><li class="leftmenu"><a href="/java-zoneoffset">Java ZoneOffset</a></li><li class="leftmenu"><a href="/java-year">Java Year</a></li><li class="leftmenu"><a href="/java-yearmonth">Java YearMonth</a></li><li class="leftmenu"><a href="/java-period">Java Period</a></li><li class="leftmenu"><a href="/java-duration">Java Duration</a></li><li class="leftmenu"><a href="/java-instant">Java Instant</a></li><li class="leftmenu"><a href="/java-dayofweek-enum">Java DayOfWeek enum</a></li><li class="leftmenu"><a href="/java-month-enum">Java Month enum</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading1"><button aria-controls="flush-collapse1" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse1" data-bs-toggle="collapse" type="button">Java Date (Classical)</button></h2><div aria-labelledby="flush-heading1" class="accordion-collapse collapse show" id="flush-collapse1"><div class="accordion-body"><ul><li class="leftmenu"><a href="/java-util-date">java.util.Date</a></li><li class="leftmenu"><a href="/java-sql-date">java.sql.Date</a></li><li class="leftmenu"><a href="/java-util-calendar">Java Calendar</a></li><li class="leftmenu"><a href="/java-util-timezone">Java TimeZone</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading2"><button aria-controls="flush-collapse2" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse2" data-bs-toggle="collapse" type="button">Java Date Format</button></h2><div aria-labelledby="flush-heading2" class="accordion-collapse collapse show" id="flush-collapse2"><div class="accordion-body"><ul><li class="leftmenu"><a href="/java-date-format">DateFormat</a></li><li class="leftmenu"><a href="/java-simpledateformat">SimpleDateFormat</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading3"><button aria-controls="flush-collapse3" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse3" data-bs-toggle="collapse" type="button">Current Date Time</button></h2><div aria-labelledby="flush-heading3" class="accordion-collapse collapse show" id="flush-collapse3"><div class="accordion-body"><ul><li class="leftmenu"><a href="/java-get-current-date">Get Current Date and Time in Java</a></li></ul></div></div></div></div></div></div><div class="col-12 col-md-7"><div class="overview"><div id="city"><table><tr><td><div id="bottomnextup"><a class="next" href="java-localdate">next →</a></div><h1 class="h1">Java Date and Time</h1><div style="font-size:14px;margin-top:5px;margin-bottom:5px;color:#6f6e6e"><span>12 Feb 2025</span> | <span><i aria-hidden="true" class="fa fa-clock-o"></i> 6 min read</span></div><p>The java.time, java.util, java.sql and java.text packages contains classes for representing date and time. Following classes are important for dealing with date in Java.</p><h2 class="h2">Java 8 Date/Time API</h2><p>Java provide the date and time functionality with the help of two packages java.time and java.util. The package java.time is introduced in Java 8, and the newly introduced classes tries to overcome the shortcomings of the legacy java.util.Date and java.util.Calendar classes.</p><ul class="points"><li><a href="java-localdate">java.time.LocalDate class</a></li><li><a href="java-localtime">java.time.LocalTime class</a></li><li><a href="java-localdatetime">java.time.LocalDateTime class</a></li><li><a href="java-monthday">java.time.MonthDay class</a></li><li><a href="java-offsettime">java.time.OffsetTime class</a></li><li><a href="java-offsetdatetime">java.time.OffsetDateTime class</a></li><li><a href="java-clock">java.time.Clock class</a></li><li><a href="java-zoneddatetime">java.time.ZonedDateTime class</a></li><li><a href="java-zoneid">java.time.ZoneId class</a></li><li><a href="java-zoneoffset">java.time.ZoneOffset class</a></li><li><a href="java-year">java.time.Year class</a></li><li><a href="java-yearmonth">java.time.YearMonth class</a></li><li><a href="java-period">java.time.Period class</a></li><li><a href="java-duration">java.time.Duration class</a></li><li><a href="java-instant">java.time.Instant class</a></li><li><a href="java-dayofweek-enum">java.time.DayOfWeek enum</a></li><li><a href="java-month-enum">java.time.Month enum</a></li></ul><h3 class="h3">java.time.LocalDate Class</h3><p>Represents a date without time, such as 2024-05-30.</p><p>Useful for representing birthdays, anniversaries, or any date-based event without the need for time.</p><div class="codeblock"><textarea class="java" name="code">
LocalDate today = LocalDate.now();
LocalDate birthday = LocalDate.of(1990, Month.MAY, 15);
</textarea></div><h3 class="h3">java.time.LocalTime Class</h3><p>Represents a time without a date, such as 10:15:30.</p><p>Ideal for representing times of day, such as business opening hours or train schedules.</p><div class="codeblock"><textarea class="java" name="code">
LocalTime now = LocalTime.now();&lt;p&gt;&lt;/p&gt;
&lt;p&gt;LocalTime movieTime = LocalTime.of(18, 30);
&lt;/p&gt;</textarea></div><h3 class="h3">java.time.LocalDateTime Class</h3><p>Combines date and time without time zone information.</p><p>Useful for timestamping events in local time.</p><div class="codeblock"><textarea class="java" name="code">
LocalDateTime meeting = LocalDateTime.of(2024, Month.MAY, 30, 14, 30);
</textarea></div><h3 class="h3">java.time.ZonedDateTime Class</h3><p>Combines date and time with time zone information.</p><p>Useful for global timestamps that need time zone awareness.</p><div class="codeblock"><textarea class="java" name="code">
ZonedDateTime zdt = ZonedDateTime.now(ZoneId.of("America/New_York"));
</textarea></div><h3 class="h3">java.time.OffsetTime Class</h3><p>Represents time with a fixed offset from UTC.</p><div class="codeblock"><textarea class="java" name="code">
OffsetTime offsetTime = OffsetTime.now(ZoneOffset.of("+02:00"));
</textarea></div><h3 class="h3">java.time.OffsetDateTime Class</h3><p>Represents date and time with a fixed offset from UTC.</p><div class="codeblock"><textarea class="java" name="code">
OffsetDateTime offsetDateTime = OffsetDateTime.now(ZoneOffset.of("+02:00"));
</textarea></div><h3 class="h3">java.time.Clock Class</h3><p>Provides access to the current instant, date, and time using a time-zone.</p><div class="codeblock"><textarea class="java" name="code">
Clock clock = Clock.systemUTC();
</textarea></div><h3 class="h3">java.time.Instant Class</h3><p>Represents a moment on the timeline in nanoseconds since the epoch (1970-01-01T00:00:00Z).</p><div class="codeblock"><textarea class="java" name="code">
Instant instant = Instant.now();
</textarea></div><h3 class="h3">java.time.Duration Class</h3><p>Measures time in seconds and nanoseconds between two instants.</p><div class="codeblock"><textarea class="java" name="code">
Duration duration = Duration.between(instant1, instant2);
</textarea></div><h3 class="h3">java.time.Period Class</h3><p>Measures the amount of time in years, months, and days between two dates.</p><div class="codeblock"><textarea class="java" name="code">
Period period = Period.between(startDate, endDate);
</textarea></div><h3 class="h3">java.time.ZoneId Class</h3><p>Represents a time zone ID, such as Europe/Paris.</p><div class="codeblock"><textarea class="java" name="code">
ZoneId zoneId = ZoneId.of("Europe/Paris");
</textarea></div><h3 class="h3">java.time.ZoneOffset Class</h3><p>Represents a time zone offset from UTC.</p><div class="codeblock"><textarea class="java" name="code">
ZoneOffset offset = ZoneOffset.of("+02:00");
</textarea></div><h3 class="h3">java.time.format.DateTimeFormatter Class</h3><p>Used for parsing and formatting date-time objects.</p><div class="codeblock"><textarea class="java" name="code">
DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MM-yyyy");
String formattedDate = today.format(formatter);
</textarea></div><h2 class="h2">Classical Date/Time API</h2><p>But classical or old Java Date API is also useful. Let's see the list of classical Date and Time classes.</p><ul class="points"><li><a href="java-util-date">java.util.Date class</a></li><li><a href="java-sql-date">java.sql.Date class</a></li><li><a href="java-util-calendar">java.util.Calendar class</a></li><li>java.util.GregorianCalendar class</li><li><a href="java-util-timezone">java.util.TimeZone class</a></li><li>java.sql.Time class</li><li>java.sql.Timestamp class</li></ul><h3 class="h3">java.util.Date Class</h3><p>Represents a specific instant in time, with millisecond precision.</p><div class="codeblock"><textarea class="java" name="code">
Date date = new Date();
</textarea></div><h3 class="h3">java.sql.Date Class</h3><p>A thin wrapper around java.util.Date that allows JDBC to identify this as an SQL DATE value.</p><div class="codeblock"><textarea class="java" name="code">
java.sql.Date sqlDate = java.sql.Date.valueOf("2024-05-30");
</textarea></div><h3 class="h3">java.util.Calendar Class</h3><p>Abstract class for converting between a specific instant in time and a set of calendar fields.</p><div class="codeblock"><textarea class="java" name="code">
Calendar calendar = Calendar.getInstance();
calendar.set(2024, Calendar.MAY, 30);
</textarea></div><h3 class="h3">java.util.GregorianCalendar Class</h3><p>Concrete subclass of Calendar that provides the standard calendar system used by most of the world.</p><div class="codeblock"><textarea class="java" name="code">
GregorianCalendar gregorianCalendar = new GregorianCalendar(2024, Calendar.MAY, 30);
</textarea></div><h3 class="h3">java.util.TimeZone Class</h3><p>Represents a time zone offset and figures out daylight savings.</p><div class="codeblock"><textarea class="java" name="code">
TimeZone timeZone = TimeZone.getTimeZone("GMT");
</textarea></div><h3 class="h3">java.sql.Time Class</h3><p>A wrapper around java.util.Date that allows the JDBC API to identify this as an SQL TIME value.</p><div class="codeblock"><textarea class="java" name="code">
java.sql.Time sqlTime = java.sql.Time.valueOf("14:30:00");
</textarea></div><h3 class="h3">java.sql.Timestamp Class</h3><p>It extends java.util.Date class to provide nanosecond precision.</p><div class="codeblock"><textarea class="java" name="code">
java.sql.Timestamp timestamp = java.sql.Timestamp.valueOf("2024-05-30 14:30:00.123456789");
</textarea></div><h3 class="h3">java.text.DateFormat Class</h3><p>Abstract class for date/time formatting subclasses that formats and parses dates or times.</p><div class="codeblock"><textarea class="java" name="code">
DateFormat dateFormat = DateFormat.getDateInstance(DateFormat.LONG);
String formattedDate = dateFormat.format(date);
</textarea></div><h3 class="h3">java.text.SimpleDateFormat Class</h3><p>Concrete class for formatting and parsing dates in a locale-sensitive manner.</p><div class="codeblock"><textarea class="java" name="code">
SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy");
String formattedDate = sdf.format(date);
</textarea></div><h2 class="h2">Formatting Date and Time</h2><p>We can format date and time in Java by using the following classes:</p><ul class="points"><li><a href="java-date-format">java.text.DateFormat class</a></li><li><a href="java-simpledateformat">java.text.SimpleDateFormat class</a></li></ul><h3 class="h3">Drawbacks of existing Date/Time API's</h3><ol class="points"><li><strong>Thread Safety:</strong> The existing classes such as Date and Calendar does not provide thread safety. Hence it leads to hard-to-debug concurrency issues that are needed to be taken care by developers. The new Date and Time APIs of Java 8 provide thread safety and are immutable, hence avoiding the concurrency issue from developers.</li><li><strong>Bad API Designing:</strong> The classic Date and Calendar APIs does not provide methods to perform basic day-to-day functionalities. The Date and Time classes introduced in Java 8 are ISO-centric and provides number of different methods for performing operations regarding date, time, duration and periods.</li><li><strong>Difficult Time Zone Handling:</strong> To handle the time-zone using classic Date and Calendar classes is difficult because the developers were supposed to write the logic for it. With the new APIs, the time-zone handling can be easily done with Local and ZonedDate/Time APIs.</li></ol><h3 class="h3">New Date Time API in Java 8</h3><p>The new date API helps to overcome the drawbacks mentioned above with the legacy classes. It includes the following classes:</p><p><strong>java.time.LocalDate:</strong> It represents a year-month-day in the ISO calendar and is useful for representing a date without a time. It can be used to represent a date only information such as a birth date or wedding date.</p><p><strong>java.time.LocalTime:</strong> It deals in time only. It is useful for representing human-based time of day, such as movie times, or the opening and closing times of the local library.</p><p><strong>java.time.LocalDateTime:</strong> It handles both date and time, without a time zone. It is a combination of LocalDate with LocalTime.</p><p><strong>java.time.ZonedDateTime:</strong> It combines the LocalDateTime class with the zone information given in ZoneId class. It represents a complete date time stamp along with timezone information.</p><p><strong>java.time.OffsetTime:</strong> It handles time with a corresponding time zone offset from Greenwich/UTC, without a time zone ID.</p><p><strong>java.time.OffsetDateTime:</strong> It handles a date and time with a corresponding time zone offset from Greenwich/UTC, without a time zone ID.</p><p><strong>java.time.Clock :</strong> It provides access to the current instant, date and time in any given time-zone. Although the use of the Clock class is optional, this feature allows us to test your code for other time zones, or by using a fixed clock, where time does not change.</p><p><strong>java.time.Instant :</strong> It represents the start of a nanosecond on the timeline (since EPOCH) and useful for generating a timestamp to represent machine time. An instant that occurs before the epoch has a negative value, and an instant that occurs after the epoch has a positive value.</p><p><strong>java.time.Duration :</strong> Difference between two instants and measured in seconds or nanoseconds and does not use date-based constructs such as years, months, and days, though the class provides methods that convert to days, hours, and minutes.</p><p><strong>java.time.Period :</strong> It is used to define the difference between dates in date-based values (years, months, days).</p><p><strong>java.time.ZoneId :</strong> It states a time zone identifier and provides rules for converting between an Instant and a LocalDateTime.</p><p><strong>java.time.ZoneOffset :</strong> It describe a time zone offset from Greenwich/UTC time.</p><p><strong>java.time.format.DateTimeFormatter :</strong> It comes up with various predefined formatter, or we can define our own. It has parse() or format() method for parsing and formatting the date time values.</p><h2 class="h2">Advantages of Java 8 Date/Time API</h2><p><strong>Immutability and Thread Safety</strong></p><p>Classes in the java.time package are immutable and thread-safe by design.</p><p><strong>Rich Set of Utilities</strong></p><p>The API provides numerous methods to handle common date and time operations, making code more readable and maintainable.</p><p><strong>Enhanced Time Zone Support</strong></p><p>The java.time package includes comprehensive support for time zones with ZoneId and ZonedDateTime class.</p><p><strong>Clarity and Precision</strong></p><p>The new API offers more precise time measurements and clear distinctions between different types of date and time representations (for example, LocalDate vs. ZonedDateTime).</p><h3 class="h3">Example Usage of Java 8 Date/ Time API</h3><p><strong>Parsing and Formatting</strong></p><div class="codeblock"><textarea class="java" name="code">
DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss");
LocalDateTime dateTime = LocalDateTime.parse("30-05-2024 14:30:00", formatter);
String formattedDateTime = dateTime.format(formatter);
</textarea></div><h3 class="h3">Calculating Differences</h3><div class="codeblock"><textarea class="java" name="code">
LocalDate startDate = LocalDate.of(2023, Month.JANUARY, 1);
LocalDate endDate = LocalDate.of(2024, Month.MAY, 30);
Period period = Period.between(startDate, endDate);
System.out.printf("Years: %d, Months: %d, Days: %d%n", period.getYears(), period.getMonths(), period.getDays());
</textarea></div><h3 class="h3">Working with Time Zones</h3><div class="codeblock"><textarea class="java" name="code">
ZonedDateTime utcTime = ZonedDateTime.now(ZoneOffset.UTC);
ZonedDateTime newYorkTime = utcTime.withZoneSameInstant(ZoneId.of("America/New_York"));
System.out.println("UTC Time: " + utcTime);
System.out.println("New York Time: " + newYorkTime);
</textarea></div><h2 class="h2">Conclusion</h2><p>The Java 8 Date/Time API offers a more robust, intuitive, and thread-safe approach to handling date and time in Java compared to the classical Date/Time API. It addresses many of the shortcomings of the older APIs, making it easier for developers to work with date and time information effectively.</p><hr/><div class="nexttopicdiv"><span class="nexttopictext">Next Topic</span><span class="nexttopiclink"><a href="java-localdate">Java LocalDate class</a></span></div><br><br><div id="bottomnext"><a class="next" href="java-localdate" style="float:right">next →</a></div><br><br/></br></br></br></td></tr></table></div><br/></div><div class="related-posts-container"><h2 class="h3">Related Posts</h2><ul class="related-posts-list"><li><a class="related-post-item" href="java-dayofweek-enum"><h3 class="h3">Java DayOfWeek enum</h3><p class="related-post-content">In Java the DayOfWeek is an enum representing the 7 days of the week. In addition with the textual enum name, every day-of-week has an int value. Declaration Let's see the declaration of java.time.DayOfWeek. public enum DayOfWeek extends Enum&amp;lt;DayOfWeek&amp;gt; implements TemporalAccessor, TemporalAdjuster Enum Constants Constants Description SUNDAY The singleton instance for the day-of-week...</p><p class="reading-time"><i aria-hidden="true" class="fa fa-clock-o"></i> 3 min read <span class="arrow-position"><svg fill="currentColor" height="1.3rem" stroke="currentColor" stroke-width="0" viewbox="0 0 512 512" width="1.3rem" xmlns="http://www.w3.org/2000/svg"><path d="M295.6 163.7c-5.1 5-5.1 13.3-.1 18.4l60.8 60.9H124.9c-7.1 0-12.9 5.8-12.9 13s5.8 13 12.9 13h231.3l-60.8 60.9c-5 5.1-4.9 13.3.1 18.4 5.1 5 13.2 5 18.3-.1l82.4-83c1.1-1.2 2-2.5 2.7-4.1.7-1.6 1-3.3 1-5 0-3.4-1.3-6.6-3.7-9.1l-82.4-83c-4.9-5.2-13.1-5.3-18.2-.3z"></path></svg></span></p></a></li><li><a class="related-post-item" href="java-monthday"><h3 class="h3">Java MonthDay</h3><p class="related-post-conten